SELECT TRIM(L.LABEL_TYPE_CD)
FROM TB_MAIL_LABEL_MAP LM
JOIN TB_MAIL_LABEL L ON L.MAIL_LABEL_ID = LM.MAIL_LABEL_ID
WHERE LM.EMP_ID = #{empId}
  AND LM.MAIL_MSG_ID = #{mailId}
ORDER BY L.MAIL_LABEL_ID

SELECT MAIL_LABEL_ID
FROM TB_MAIL_LABEL
WHERE EMP_ID = #{empId}
  AND TRIM(LABEL_TYPE_CD) = #{labelTypeCd}
  AND USE_YN = 'Y'

SELECT COUNT(1)
FROM TB_MAIL_LABEL_MAP
WHERE EMP_ID = #{empId}
  AND MAIL_MSG_ID = #{mailId}
  AND MAIL_LABEL_ID = #{labelId}

mapper.delete:
DELETE FROM TB_MAIL_LABEL_MAP LM
WHERE LM.EMP_ID = #{empId}
  AND LM.MAIL_MSG_ID = #{mailId}
  AND EXISTS (
      SELECT 1
      FROM TB_MAIL_LABEL L
      WHERE L.MAIL_LABEL_ID = LM.MAIL_LABEL_ID
        AND L.EMP_ID = LM.EMP_ID
        AND TRIM(L.LABEL_TYPE_CD) = #{labelTypeCd}
  )

